package dev.napuli;

import com.mojang.serialization.JsonOps;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;

public final class PlayerImprovementsGameTest {
    static void nearby(GameTestHelper h,List<ServerPlayer> ps){for(int i=0;i<ps.size();i++){var at=h.absolutePos(new BlockPos(1+i,2,1));ps.get(i).snapTo(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);ps.get(i).getInventory().clearContent();}}
    static void cash(ServerPlayer p,int value){NapoliStreet.credit(p,value-NapoliStreet.cash(p));}
    static PlayerTrade.Session trade(ServerPlayer a,ServerPlayer b){var s=new PlayerTrade.Session(a,b);s.accepted=true;s.confirmed.add(a.getUUID());s.confirmed.add(b.getUUID());return s;}
    static void forget(net.minecraft.server.level.ServerLevel city,UUID id){var all=new HashMap<>(city.getAttachedOrElse(CooperativeJobs.PROJECTS,Map.of()));all.remove(id.toString());city.setAttached(CooperativeJobs.PROJECTS,Map.copyOf(all));}

    @GameTest public void tradeTransfersExactComponentsAndConservesMoneyOnce(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,2,ps->{nearby(h,ps);var a=ps.get(0);var b=ps.get(1);cash(a,30);cash(b,12);
        var named=new ItemStack(Items.DIAMOND,3);named.set(DataComponents.CUSTOM_NAME,Component.literal("Original gem"));a.getInventory().setItem(0,named);b.getInventory().setItem(0,new ItemStack(Items.IRON_INGOT,7));
        var s=trade(a,b);s.a.items.put(0,named.copyWithCount(2));s.a.money=10;s.b.items.put(0,b.getInventory().getItem(0).copyWithCount(4));s.b.money=2;
        h.assertTrue(PlayerTrade.settle(s,a,b),"Both confirmed offers settle together");h.assertTrue(NapoliStreet.cash(a)==22&&NapoliStreet.cash(b)==20,"Money is conserved exactly");
        h.assertTrue(a.getInventory().countItem(Items.DIAMOND)==1&&b.getInventory().countItem(Items.DIAMOND)==2&&a.getInventory().countItem(Items.IRON_INGOT)==4,"Only selected quantities move");
        h.assertTrue(b.getInventory().getItem(1).getHoverName().getString().equals("Original gem"),"Item components survive the exchange");h.assertTrue(!PlayerTrade.settle(s,a,b),"A completed trade cannot be replayed");});h.succeed();}

    @GameTest public void editedTradeAndChangedInventoryRequireNewConfirmation(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,2,ps->{nearby(h,ps);var a=ps.get(0);var b=ps.get(1);cash(a,40);cash(b,40);a.getInventory().setItem(0,new ItemStack(Items.DIAMOND,2));var s=trade(a,b);s.a.items.put(0,a.getInventory().getItem(0).copy());s.a.money=5;s.changed();
        h.assertTrue(s.revision==1&&s.confirmed.isEmpty()&&!PlayerTrade.settle(s,a,b),"An edit clears both confirmations");s.confirmed.add(a.getUUID());s.confirmed.add(b.getUUID());a.getInventory().getItem(0).set(DataComponents.CUSTOM_NAME,Component.literal("Changed"));
        h.assertTrue(!PlayerTrade.settle(s,a,b)&&NapoliStreet.cash(a)==40&&NapoliStreet.cash(b)==40&&a.getInventory().countItem(Items.DIAMOND)==2,"Changing components after offering aborts without any transfer");});h.succeed();}

    @GameTest public void fullInventoriesGrossFundsAndDistanceAbortWithoutPartialTransfers(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,2,ps->{nearby(h,ps);var a=ps.get(0);var b=ps.get(1);cash(a,20);cash(b,20);a.getInventory().setItem(0,new ItemStack(Items.DIAMOND));for(int i=0;i<36;i++)b.getInventory().setItem(i,new ItemStack(Items.STONE,64));var s=trade(a,b);s.a.items.put(0,a.getInventory().getItem(0).copy());s.b.money=5;
        h.assertTrue(!PlayerTrade.settle(s,a,b)&&a.getInventory().countItem(Items.DIAMOND)==1&&NapoliStreet.cash(b)==20,"Insufficient incoming capacity changes neither inventory nor wallet");b.getInventory().setItem(0,ItemStack.EMPTY);s.a.money=21;s.b.money=20;h.assertTrue(!PlayerTrade.settle(s,a,b),"Each gross offer must be affordable even if the net would be affordable");s.a.money=0;s.b.money=0;b.snapTo(a.getX()+7,a.getY(),a.getZ(),0,0);h.assertTrue(!PlayerTrade.settle(s,a,b),"Walking out of range cancels admission");});h.succeed();}

    @GameTest public void tradeRejectsWalletOverflowAndFreedOutgoingSlotsAcceptIncomingItems(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,2,ps->{nearby(h,ps);var a=ps.get(0);var b=ps.get(1);cash(a,99999);cash(b,10);var s=trade(a,b);s.b.money=1;h.assertTrue(!PlayerTrade.settle(s,a,b)&&NapoliStreet.cash(b)==10,"The wallet cap cannot destroy offered money");s.b.money=0;for(int i=0;i<36;i++){a.getInventory().setItem(i,new ItemStack(Items.STONE,64));b.getInventory().setItem(i,new ItemStack(Items.IRON_INGOT,64));}s.a.items.put(0,a.getInventory().getItem(0).copy());s.b.items.put(0,b.getInventory().getItem(0).copy());h.assertTrue(PlayerTrade.settle(s,a,b)&&a.getInventory().getItem(0).is(Items.IRON_INGOT)&&b.getInventory().getItem(0).is(Items.STONE),"A full-for-full exchange uses slots released by outgoing offers");});h.succeed();}

    @GameTest public void cooperativeMaintenanceCountsRealMaterialsAndPaysExactlyOnce(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,2,ps->{nearby(h,ps);var city=h.getLevel();var a=ps.get(0);var b=ps.get(1);cash(a,0);cash(b,0);var oldIssues=city.getAttachedOrElse(CityWorkIncidents.ISSUES,Map.of());int fund=WorkEconomy.fund(city);var id=UUID.randomUUID();var group=new CompanionMeetups.Group(UUID.randomUUID(),a.getUUID(),new CityCompanion.Goal("work",a.blockPosition()),List.of(a.getUUID(),b.getUUID()),Set.of(),0);var project=new CooperativeJobs.Project(id,group.id(),a.getUUID(),"maintenance",id.toString(),a.blockPosition(),2,20,"active",group.members(),Map.of());
        try{CompanionMeetups.put(city,group);CooperativeJobs.put(city,project);city.setAttached(WorkEconomy.FUND,fund-20);var issues=new HashMap<>(oldIssues);issues.put(id.toString(),new CityWorkIncidents.Incident(id.toString(),"B1",a.blockPosition(),0,false));city.setAttached(CityWorkIncidents.ISSUES,Map.copyOf(issues));h.assertTrue(CooperativeJobs.reserved(city,id.toString()),"A cooperative job reserves the same fault against solo payment");
            for(var p:ps)p.getInventory().setItem(0,new ItemStack(Items.IRON_INGOT));CooperativeJobs.contribute(a,project);project=city.getAttachedOrElse(CooperativeJobs.PROJECTS,Map.of()).get(id.toString());h.assertTrue(project.progress()==1&&a.getInventory().countItem(Items.IRON_INGOT)==0,"Real material is consumed for each saved contribution");CooperativeJobs.contribute(b,project);project=city.getAttachedOrElse(CooperativeJobs.PROJECTS,Map.of()).get(id.toString());
            h.assertTrue(project.state().equals("completed")&&CityWorkIncidents.get(city,id.toString())==null,"The actual line fault is resolved exactly when work completes");
            var encoded=CooperativeJobs.Project.CODEC.encodeStart(JsonOps.INSTANCE,project).getOrThrow();var restored=CooperativeJobs.Project.CODEC.parse(JsonOps.INSTANCE,encoded).getOrThrow();CooperativeJobs.put(city,restored);h.assertTrue(CooperativeJobs.claim(a,restored)&&CooperativeJobs.claim(b,restored),"Saved rewards remain individually claimable");h.assertTrue(!CooperativeJobs.claim(a,restored)&&NapoliStreet.cash(a)==10&&NapoliStreet.cash(b)==10&&WorkEconomy.fund(city)==fund-20,"Payouts are proportional, conserved and cannot be replayed");
        }finally{forget(city,id);CompanionMeetups.leave(city,a.getUUID());CompanionMeetups.leave(city,b.getUUID());city.setAttached(CityWorkIncidents.ISSUES,oldIssues);city.setAttached(WorkEconomy.FUND,fund);}});h.succeed();}

    @GameTest public void cancelledCooperativeJobsRefundExactMaterialsWithoutDuplicateFundCredit(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,1,ps->{nearby(h,ps);var p=ps.getFirst();var city=h.getLevel();int fund=WorkEconomy.fund(city);var item=new ItemStack(Items.WHEAT,3);item.set(DataComponents.CUSTOM_NAME,Component.literal("Saved harvest"));var id=UUID.randomUUID();var project=new CooperativeJobs.Project(id,UUID.randomUUID(),p.getUUID(),"supply","forno",p.blockPosition(),16,24,"active",List.of(p.getUUID()),Map.of(p.getUUID().toString(),new CooperativeJobs.Contribution(3,List.of(item),false,false)));
        try{CooperativeJobs.put(city,project);city.setAttached(WorkEconomy.FUND,fund-24);CooperativeJobs.cancel(city,project);CooperativeJobs.cancel(city,project);h.assertTrue(WorkEconomy.fund(city)==fund,"Repeated cancellation returns only the originally reserved fund");for(int slot=0;slot<36;slot++)p.getInventory().setItem(slot,new ItemStack(Items.STONE,64));h.assertTrue(!CooperativeJobs.claim(p,project),"A full inventory preserves the refund for later");p.getInventory().setItem(0,ItemStack.EMPTY);h.assertTrue(CooperativeJobs.claim(p,project)&&p.getInventory().getItem(0).getCount()==3&&p.getInventory().getItem(0).getHoverName().getString().equals("Saved harvest"),"Refund preserves exact original quantities and components");h.assertTrue(!CooperativeJobs.claim(p,project),"A refund can only be claimed once");}finally{forget(city,id);city.setAttached(WorkEconomy.FUND,fund);}});h.succeed();}

    @GameTest public void proportionalSharesUseEveryEuroAndPreserveZeroContributors(GameTestHelper h){var a=UUID.randomUUID();var b=UUID.randomUUID();var c=UUID.randomUUID();var project=new CooperativeJobs.Project(UUID.randomUUID(),UUID.randomUUID(),a,"supply","forno",BlockPos.ZERO,16,25,"completed",List.of(a,b,c),Map.of(a.toString(),new CooperativeJobs.Contribution(5,List.of(),false,false),b.toString(),new CooperativeJobs.Contribution(11,List.of(),false,false)));var shares=CooperativeJobs.shares(project);h.assertTrue(shares.values().stream().mapToInt(Integer::intValue).sum()==25&&shares.get(c)==0&&shares.get(b)>shares.get(a),"Rounding assigns the complete pool according to actual contribution");h.succeed();}

    @GameTest public void houseGrantsSeparateDoorsAppliancesAndStorageAndInvalidateWithOwner(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,3,ps->{var city=h.getLevel();var home=NapoliMergellina.PROPERTIES.getFirst();var owner=ps.get(0);var guest=ps.get(1);var buyer=ps.get(2);var owners=city.getAttachedOrElse(NapoliProperties.OWNERS,Map.of());var invitations=city.getAttachedOrElse(HouseGuests.INVITATIONS,Map.of());var grants=city.getAttachedOrElse(HomePermissions.GRANTS,Map.of());
        try{var all=new HashMap<>(owners);all.put(home.id(),owner.getUUID());city.setAttached(NapoliProperties.OWNERS,Map.copyOf(all));HouseGuests.grant(city,home.id(),owner.getUUID(),guest);h.assertTrue(HomePermissions.allows(guest,home,HomePermissions.Capability.DOORS)&&!HomePermissions.allows(guest,home,HomePermissions.Capability.STORAGE)&&!HomePermissions.allows(guest,home,HomePermissions.Capability.APPLIANCES),"New guests have entry without storage or appliance rights");
            HomePermissions.put(city,home.id(),guest.getUUID(),new HomePermissions.Grant(owner.getUUID(),"roommate",false,true,false));h.assertTrue(!NapoliProperties.hasAccess(guest,home)&&HomePermissions.allows(guest,home,HomePermissions.Capability.APPLIANCES)&&!HomePermissions.allows(guest,home,HomePermissions.Capability.STORAGE),"Each capability is independent of role and keys");h.assertTrue(!NapoliProperties.owns(guest,home)&&!HouseGuests.grant(city,home.id(),guest.getUUID(),buyer),"Roommates cannot change ownership or invite others");
            var grant=HomePermissions.grant(city,home.id(),guest.getUUID());var encoded=HomePermissions.Grant.CODEC.encodeStart(JsonOps.INSTANCE,grant).getOrThrow();h.assertTrue(HomePermissions.Grant.CODEC.parse(JsonOps.INSTANCE,encoded).getOrThrow().equals(grant),"Granular permissions survive serialization");all.put(home.id(),buyer.getUUID());city.setAttached(NapoliProperties.OWNERS,Map.copyOf(all));h.assertTrue(!HomePermissions.allows(guest,home,HomePermissions.Capability.APPLIANCES)&&HomePermissions.allows(buyer,home,HomePermissions.Capability.STORAGE),"A new owner invalidates grants issued by the previous owner");
        }finally{city.setAttached(NapoliProperties.OWNERS,owners);city.setAttached(HouseGuests.INVITATIONS,invitations);city.setAttached(HomePermissions.GRANTS,grants);}});h.succeed();}

    @GameTest public void scooterRecoveryInvalidatesOldEntityTokensAndTransfersOwnership(GameTestHelper h){HousingCapacityGameTest.withPlayers(h,2,ps->{nearby(h,ps);var p=ps.get(0);var other=ps.get(1);var bike=h.spawn(Napuli.MOTORINO,1,2,1);var registry=ScooterGarage.registry(h.getLevel());var saved=registry.getAttachedOrElse(ScooterGarage.BIKES,Map.of());try{bike.setStation(4);h.assertTrue(ScooterGarage.observe(bike,p),"First rider claims a legacy scooter");var old=ScooterGarage.get(p.level(),bike.getUUID());var stored=ScooterGarage.stored(old);ScooterGarage.put(p.level(),stored);h.assertTrue(!ScooterGarage.observe(bike,null)&&bike.isRemoved(),"The old loaded entity is invalid after a recovery generation is issued");var token=ScooterGarage.token(stored);h.assertTrue(ScooterGarage.matches(stored,p,token)&&!ScooterGarage.matches(stored,other,token),"Only the owner can use the recovery token");var encoded=ScooterGarage.Bike.CODEC.encodeStart(JsonOps.INSTANCE,stored).getOrThrow();h.assertTrue(ScooterGarage.Bike.CODEC.parse(JsonOps.INSTANCE,encoded).getOrThrow().equals(stored)&&stored.station()==4,"Location, owner, generation and radio station survive saves");
            var next=ScooterGarage.stored(stored);h.assertTrue(!ScooterGarage.matches(next,p,token),"An older copied receipt cannot recreate the recovered scooter");h.assertTrue(ScooterGarage.tradable(p,List.of(token)),"A legitimate stored scooter may be offered");ScooterGarage.transfer(p,other,List.of(token));h.assertTrue(!ScooterGarage.tradable(p,List.of(token))&&ScooterGarage.tradable(other,List.of(token)),"Trade transfers the vehicle registry, not just its item");
        }finally{bike.discard();registry.setAttached(ScooterGarage.BIKES,saved);}});h.succeed();}

    @GameTest public void binaryTrafficLookupMatchesEveryFrameBoundaryAndCacheHonorsDelays(GameTestHelper h){for(var line:CityNetwork.lines()){var plan=CityNetwork.plan(line);for(var frame:plan.frames())for(int phase:new int[]{frame.start(),frame.end()-1}){var linear=plan.frames().stream().filter(f->phase>=f.start()&&phase<f.end()).findFirst().orElseThrow();h.assertTrue(CityNetwork.frameAt(plan,phase).equals(linear),"Binary lookup agrees at every stop and segment boundary");}var one=CityNetwork.position(h.getLevel(),line,0);h.assertTrue(CityNetwork.position(h.getLevel(),line,0)==one,"Repeated reads reuse the current tick's immutable position");CityNetwork.delay(h.getLevel(),CityNetwork.vehicleKey(line,0),1);h.assertTrue(CityNetwork.position(h.getLevel(),line,0).phase()==Math.floorMod(one.phase()-1,plan.cycle()),"A live delay invalidates the cache immediately");}h.succeed();}

    @GameTest public void npcIndexImmediatelyReflectsSavedCensusReplacement(GameTestHelper h){var city=h.getLevel();var before=city.getAttached(NapoliCivicLife.CENSUS);var id=UUID.randomUUID();try{var first=new NapoliCivicLife.Citizen(id,"Original",false,0,10,-1,"","","",true);city.setAttached(NapoliCivicLife.CENSUS,new NapoliCivicLife.Census(0,List.of(first)));h.assertTrue(NapoliCivicLife.profile(city,id)==first,"Index returns the original saved citizen");var updated=first.withMoney(25,first.job());city.setAttached(NapoliCivicLife.CENSUS,new NapoliCivicLife.Census(0,List.of(updated)));h.assertTrue(NapoliCivicLife.profile(city,id)==updated&&NapoliCivicLife.profile(city,id).balance()==25,"Replacement invalidates the index without waiting a tick");city.setAttached(NapoliCivicLife.CENSUS,new NapoliCivicLife.Census(1,List.of()));h.assertTrue(NapoliCivicLife.profile(city,id)==null,"Removed citizens cannot survive in the index");}finally{if(before==null)city.removeAttached(NapoliCivicLife.CENSUS);else city.setAttached(NapoliCivicLife.CENSUS,before);}h.succeed();}

    @GameTest public void effectPreferencesArePersonalAndInitialEconomyCoversEssentials(GameTestHelper h){h.assertTrue(CityEffects.particleCount(0,18,false)==18&&CityEffects.particleCount(CityEffects.LIGHT,18,false)==4,"Light mode bounds particle work while normal mode preserves it");h.assertTrue(CityEffects.particleCount(CityEffects.PARTICLES,18,false)==0&&CityEffects.particleCount(CityEffects.FLASHES,18,true)==0&&CityEffects.particleCount(CityEffects.FLASHES,18,false)==18,"Particle and flashing options act independently");h.assertTrue(CityLifeConfig.settings.startingCash>=PlayerEconomyGuide.starterBudget(),"The default first wallet covers the example essential budget");for(var c:NapoliEmployment.Contract.values())h.assertTrue(PlayerEconomyGuide.hoursFor(6,c.job.wage)==1&&PlayerEconomyGuide.hoursFor(30,c.job.wage)<=4,"Base replacement and first upgrade remain reachable at every starting wage");Napuli.LOGGER.info("[ECONOMY] starter={} essential_budget={} minimum_work_seconds=50 wages=9..13 first_upgrade=30 plus material",CityLifeConfig.settings.startingCash,PlayerEconomyGuide.starterBudget());h.succeed();}
}
